INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(352300, 0, 3523, 0, 0, 8, 'Netherstorm', 'Netherstorm was once the Plains of Farahlon, green country that a Kirin Tor mage could compare to Westfall only months ago. When Ner''zhul''s portals tore Draenor apart it was left a scatter of floating islands at the edge of the Twisting Nether, and now the forces of Prince Kael''thas are finishing the ruin. From Tempest Keep, the fortress his blood elves hold, they work great manaforges that pull energy out of the sky and pipe it away underground, and the strain is tearing the land apart; one goblin scientist gives the region only months. Many have come to exploit or oppose them. The ethereal traders of the Consortium rule from the Stormspire, the Protectorate hunts a void lord and the renegade Ethereum, the goblins of Area 52 build a rocket to fly into the Nether, and the ghosts of a Kirin Tor village mourn their dead. In the north the Burning Legion builds fel reavers under the eredar Socrethar, while envoys of the Aldor and the Scryers quarrel at the Area 52 inn.', 'warcraft.wiki.gg/wiki/Netherstorm (Farahlon, Ner''zhul''s portals, edge of the Twisting Nether, Kael''thas and Tempest Keep, manaforges, Consortium, Protectorate, Area 52, Legion forge bases, Socrethar); npc_text 9826 (Ravandwyr: once the Plains of Farahlon); npc_text 9901 (Vargoth image: mere months ago the fields would not have looked out of place in Westfall); quest 10189 description (manaforges sucking energy from the sky); quest 10193 description (warp-energy delivered via underground pipes); quest 10183 reward text (nether energies will rip everything to shreds in a few months); npc_text 10022 (innkeeper: arrivals from Shattrath arguing); quests 10339, 10437, 10855 descriptions'),
(352301, 1, 3523, 1, 0, 8, 'Area 52', 'Area 52 is a walled goblin town on the southwestern island of Netherstorm and the headquarters of B.O.O.M., the Braintrust of Orbital Operations and Mechanics. Its pride is the half-built X-52 Nether-Rocket, overseen by Rocket-Chief Fuselage. Bruisers and towering death machines keep the peace, and sappers work a fissure the goblins blasted through the middle of town, where a few workers glow suspiciously and the lead sapper insists radiation is nothing to worry about. The town is neutral ground. A Kirin Tor apprentice waits here for help, a Consortium agent hunts traitors, and envoys of the Aldor and the Scryers, newly arrived from Shattrath, argue so constantly that the innkeeper worried they would drive off trade.', 'warcraft.wiki.gg/wiki/Area_52 (neutral goblin town, southwestern island, B.O.O.M., X-52, bruisers and death machines, Irradiated Worker and Manager); npc_text 9844 (Fuselage: Braintrust of Orbital Operations and Mechanics); quest 10203 description (fissure running through Area 52, we did that); npc_text 9869 (Blastfizzle: radiation, no need to worry); npc_text 10022 (Innkeeper Remi Dodoso); zone_areas 3712: Ravandwyr 19217, Khay''ji 19880, Orelis, Karja, Thalodien, Larynna, Area 52 Bruiser, Death Machine, Irradiated Worker 19610'),
(352302, 1, 3523, 2, 0, 8, 'Ruins of Enkaat', 'North of Area 52 lie the Ruins of Enkaat, an old draenei settlement fallen to rubble. Its dead have not left. Disembodied vindicators, protectors and even exarchs drift among the broken walls and attack anyone who comes near, and the goblins have taken a keen interest in the crystals they carry. The goblins of Area 52 gather etherlithium crystals here for their rocket''s engine matrix, a goblin bot specialist salvages fragile draenei machines with the help of a robot called the Maxx A. Million, and the Kirin Tor apprentice Ravandwyr has heard that a crystal carried by these ghosts could mend his master''s broken staff.', 'quest 10186 description (crystals at the Ruins of Enkaat, never mind the draenei ghosts); quests 10190, 10191 (Bot-Specialist Alley, Maxx A. Million Mk. V, fragile draenei machines, ghosts); quest 10300 description (crystals carried by the ghosts at the Enkaat Ruins); zone_areas 3725: Disembodied Vindicator 18872, Protector 18873, Exarch 21058, Etherlithium Matrix Crystal x25, Alley 19578; warcraft.wiki.gg/wiki/Netherstorm (Ruins of Enkaat northwest of Area 52, restless draenei spirits)'),
(352303, 1, 3523, 3, 0, 8, 'Arklon Ruins', 'Southeast of Area 52 stand the Arklon Ruins, another old draenei settlement. When Archmage Vargoth''s apprentice Ravandwyr fled the attack on the Violet Tower, he sought refuge here and walked straight into the leading edge of a Burning Legion force, which wrested his master''s staff from him; it ended in the hands of their leader, Ekkorash. The demons have stayed. Doomguard keep watch while artifact seekers dig for something under the dreadlord Pentatharon, and the goblin sapping crew that worked here left its machinery behind when the Legion moved in. Beyond the ruins, Farahlon giants walk the heights of Arklonis Ridge.', 'npc_text 9828 (Ravandwyr: refuge in the old draenei settlement of Arklon, Legion force, staff wrested from him); quest 10173 description (Arklon Ruins southeast, Ekkorash has the staff); creature 19493 Ekkorash the Inquisitor; quest 10265 description and reward (Pentatharon, Legion excavating, searching for something); quest 10203 description (B.O.O.M. operation at the Arklon Ruins until the Legion moved in); zone_areas 3723: Artifact Seeker 19852, Felblade Doomguard 19853, Pentatharon 20215, goblin equipment objects; 3921: Farahlon Giant x6'),
(352304, 1, 3523, 4, 0, 8, 'The Crumbling Waste', 'The Crumbling Waste is the broken rim of the island south of Area 52, a long ledge where the land gives way to open sky. Phase hunters drift in from the nether along its edges, nether rays and mana snappers roam the slopes, and sundered rumblers and warp aberrations haunt the southern shelf. The goblins see resources everywhere. Chief Engineer Trep sends crews to wring solid power out of the rumblers and aberrations for the X-52''s engines, and Rocket-Chief Fuselage has posted a wanted notice for Netherock, king of the local mountain giants, who has been interfering with operations all along the south ledge.', 'quest 10190 description (phase hunters floating in from the nether at the island''s edges); quest 10226 description (sundered rumblers and warp aberrations on the ledge of the Crumbling Wastes to the south); quest 10701 description (Netherock, king of the local mountain giants, south ledge of the island); zone_areas 3721: Phase Hunter, Nether Beast, Mana Snapper, Sundered Rumbler, Nether Ray, Warp Aberration, Netherock 20772'),
(352305, 1, 3523, 5, 0, 8, 'Manaforge B''naar', 'Manaforge B''naar, west of Area 52, was the first of Kael''thas''s great purple engines that the envoys from Shattrath set out to study. Its warp-masters and warp-engineers oversee the gathering of what they call warp-energy and its delivery through underground pipes to a distant destination, while geologists survey the ground and magisters and bloodwarders stand guard, with a ballista team posted outside. The magisters have refined their use of mana crystals until they can siphon great amounts of energy in seconds, attuning small bloodgem shards to the great charged crystals of the forge.', 'quest 10189 description (manaforge, large purple buildings, Captain Arathyn''s ballista team); quest 10193 description (warp-masters, warp-engineers, geologists, underground pipes); quest 10204 description and reward (bloodgem crystals, magnified addiction); quest 10313 description and reward (pipeline ends, energies could shatter Outland); quests 10243, 10245, 10299 (console code like naaru technology); quest 10261 description (B''naar to the west of Area 52); zone_areas 3726: Sunfury Bloodwarder, Geologist, Warp-Engineer, Magister, Warp-Master, Overseer Theredis 20416'),
(352306, 1, 3523, 6, 0, 8, 'The Heap', 'South of Area 52 lies the Heap, a junkyard of salvage that the goblins of B.O.O.M. consider their claim. The Zaxxis ethereals disagree. Once part of the Consortium, the Zaxxis broke away to go into business for themselves and have even cut deals with the Sunfury blood elves, so the Consortium''s Nether-Stalker Khay''ji, who infiltrated them and attacked their leader before escaping to Area 52, wants their insignia. The goblins simply raid the ethereals'' camp for its technology. Nearby sits a scrapped fel reaver, and the goblin salvager N. D. Meancamp, crouched where the Zaxxis cannot see him, is determined to have its heart.', 'quest 10206 description (The Heap to the south is ours, ethereals stealing); quest 10262 description (Zaxxis cut relationship with the Consortium, deals with the Sunfury); quest 10205 description (Nesaad survived my attack, camp in the southwestern corner of the Heap); quest 10309 description (scrapped fel reaver, Zaxxis ethereals); npc_text 9904 (Meancamp: keep it down, this is MY claim); zone_areas 3729: Zaxxis Raider, Zaxxis Stalker, Warp-Raider Nesaad 19641, Scrapped Fel Reaver 20243, Meancamp 19690'),
(352307, 1, 3523, 7, 0, 8, 'Eco-Dome Midrealm', 'Across the bridge east of Area 52, the Consortium has raised Eco-Dome Midrealm, a bubble of living green on the ruined plains. Inside, lynxes, moths and crocolisks thrive among plants that grow faster than they should, including the ivory bell, a healing herb the ethereals sell at a steep price to the Cenarion Expedition. At the Midrealm Post the trader Gahruj handles the Consortium''s quarrels with the blood elves and the technician Mehrdad worries over a failing dome generator, while two goblins watch the ethereals closely: Mama Wheeler of Area 52, eager to learn their secrets, and a fellow who claims to be a simple furrier.', 'quest 10266 description (east of Area 52 across the bridge, Midrealm Post just inside Eco-Dome Midrealm); quest 10348 description and reward (ivory bell for the Cenarion Expedition, a lot of money); quest 10418 reward (domes accelerate growth); quest 10417 description (generator damage); npc_text 9947 (Gahruj on the blood elves); npc_text 9919 (Mama Wheeler: learn a lot, maybe get some for myself); quest 10433 description (Shauly posing as a simple furrier); zone_areas 3877/3851: Ripfang Lynx, Shimmerwing Moth, Barbscale Crocolisk, Ivory Bell; Gahruj, Mehrdad, Mama Wheeler, Shauly Pore'),
(352308, 1, 3523, 8, 0, 8, 'The Scrap Field', 'East of Eco-Dome Midrealm, the Burning Legion has seized a goblin salvage claim, the Scrap Field. Huge fel reaver parts litter the ground, gan''arg engineers and mo''arg doomsmiths labor among them, and their overseer Doomclaw keeps to the eastern end beneath the great pipe, driving his workers and promising to come for the little goblins. The demons never run short of hands. South of the field, at a camp they call Invasion Point: Destroyer, a warp-gate brings in a steady flow of reinforcements, and the Consortium''s Drijya has slipped down there to sabotage it, pylon by pylon.', 'quest 10232 description (Legion moved in on our claim at the Scrap Field); quest 10234 description (to the east of Midrealm Post, huge fel reaver parts); quest 10235 description (Doomclaw in the eastern part under the pipe); creature_text 19738 (Doomclaw); quest 10311 description (reinforcements from Invasion Point: Destroyer to the south); quest 10310 and creature_text 20281 (pylons, heat manifold); zone_areas 3727: Gan''arg Engineer, Mo''arg Doomsmith, Doomclaw 19738, Fel Reaver Part; 3882: Warp-Gate Engineer'),
(352309, 1, 3523, 9, 0, 8, 'Manaforge Coruu', 'Manaforge Coruu stands east of Area 52 near Kirin''Var, and its arcanist boasts of having more than doubled the energy it sends to Tempest Keep. A regiment of Sunfury arcanists and researchers works here under Arcanist Ardonis, and Spellbinder Maryana keeps the Sigil of Krasus, taken from Archmage Vargoth. Arcane golems patrol the forge. It is watched all the same: Scryer spies keep a secret landing outside it, waiting for the chance to slip among Kael''s followers and learn what passes between their commanders.', 'npc_text 9926 (Ardonis: more than doubled the energy sent to Tempest Keep, another Ultris); quests 10194, 10321 (Coruu to the east); quest 10246 description (regiment of arcanists and researchers); quest 10188 description (Kael''thas gave the sigil to Spellbinder Maryana); quests 10652, 10197, 10198 (spies, illusion, Dawnforge meeting Ardonis); creature_text 19831, 19830, 21504 groups 0-3 (Pathaleon the Calculator''s Image); zone_areas 3730: Ardonis 19830, Dawnforge 19831, Maryana 19593, Caledis 19840, Lariel 19839, Seylanna 20397; src/server/scripts/Outland/zone_netherstorm.cpp (Dawnforge, Ardonis and Pathaleon image event at Coruu); quest 10194 description (secret landing spot outside the manaforge); quest 10198 description (arcane golems patrolling)'),
(352310, 1, 3523, 10, 0, 8, 'Kirin''Var Village', 'Kirin''Var Village was built by the Kirin Tor mages of the Alliance expedition once they knew they were trapped in Outland, and by the custodian''s count it held for twenty years against countless orc assaults. It did not survive Kael''thas. His forces leveled the town in an assault that began with a thundering noise and a blinding flash, and ever since, beings of pure mana have streamed into the ruins of Wizard Row. Now the dead keep the village. Ghostly apprentices haunt the Town Square, a maddened spectral smith lingers in his old workshop, tormented souls wander the Chapel Yard, and an old farmer pines for his lost cow. By the lieutenant-sorcerer''s account, only two spirits remember who they were.', 'quest_template 10179 description (Vargoth: expedition trapped, Kirin Tor contingent built Kirin''Var on the Plains of Farahlon); npc_text 9848 (Dieworth: 20 long years and countless orc assaults); quest 10343 description and reward (thundering noise and flash, mana bomb, rift in the nether, mana creatures); quest 10185 description (mana elementals drawn to the ruins of Wizard Row); npc_text 9847 (Morran: only the custodian and I retain our identities); quests 10331, 10332 (Master Rhonsus attacked); quest 10334 (Thadell searched the fields and Chapel Yard for Bessy); zone_areas 3934, 3935, 3879: Severed Spirit, Kirin''Var Apprentice, Rhonsus 20410, Mana Seeker, Mageslayer, Mana Bomb Fragment, Tormented Soul, Tormented Citizen; warcraft.wiki.gg/wiki/Kirin''Var_Village (mana bomb dropped on Wizard Row)'),
(352311, 1, 3523, 11, 0, 8, 'The Violet Tower', 'At the heart of Kirin''Var rises the Violet Tower, sanctuary and prison to Archmage Vargoth. When Kael''thas took the village he stripped the archmage of his possessions and sealed the tower with a curse that no member of the Kirin Tor may cross in either direction, so that Vargoth''s own people cannot reach him. An arcane golem named Ar''kelos guards the base and smothers the archmage''s magic, and the ward keeps Vargoth from scrying out the force that holds it in place. Kael''thas was always a talented mage, the archmage admits, but he had never seen power like the prince wielded in the attack.', 'quest 10174 description (sanctuary and prison, Kirin Tor can neither enter nor leave); npc_text 9848 (ward forbids passage of any of the Kirin Tor); quest 10188 description (Kael''thas divested me of my possessions); quest 10319 description (Naberius handed over the secrets to the tower''s defense); quest 10176 description and reward (Ar''kelos at the bottom of the tower, dampening field); quests 10256, 10257 (Commander Sarannis holds the keystone in Tempest Keep); quest 10176 log text (Violet Tower at the center of Kirin''Var Village); quest 10256 description (the ward keeps me from scrying out the force; never seen power like it)'),
(352312, 1, 3523, 12, 0, 8, 'Sunfury Hold', 'North of the Violet Tower lies Sunfury Hold, the camp to which Kael''thas''s forces withdrew after destroying Kirin''Var. The village''s ghostly custodian says the very soldiers who killed them toast their amazing victory here, among the tents and ballistae, the archers and flamekeepers. Its commander, Spellreaver Marathelle, carried off the heliotrope oculus that unlocks Krasus''s Compendium during the attack, no doubt taking it for a pretty bauble. Custodian Dieworth wants the garrison slain, and Lieutenant-Sorcerer Morran wants every tent and siege engine burned to ash, so that Kael''s zealous followers have nothing to return to.', 'quest 10222 description (withdrew to Sunfury Hold to the northeast, toast their amazing victory); quest 10301 description and reward (Spellreaver Marathelle looted the oculus, Sunfury Hold northeast of the tower, local commander); quest 10233 description (Morran: tents and artillery must burn, zealous and tenacious); creature_text 19926; zone_areas 3837: Sunfury Archer, Sunfury Flamekeeper, Invis BE Ballista, Invis BE Tent, Marathelle 19926'),
(352313, 1, 3523, 13, 0, 8, 'Manaforge Duro', 'Manaforge Duro, east of Eco-Dome Midrealm, is the forge slipping out of its masters'' hands. Its rising output has drawn swarms of errant mana creatures, the Sunfury garrison is losing control, and the Aldor fear that an explosion here could set off a chain reaction across Outland. Its defenders include notorious names. Master Daellis Dawnstrike, the crimson-armored archer who led the attack on Kirin''Var, has been sent here to restore order, and Summoner Kanthin keeps Archmage Vargoth''s familiar, Glacius, as a trophy. The blood elves also hold a shipment of Consortium surveying equipment they never paid for, and west of the forge roams Apex, a giant that bears great crystals.', 'quest 10322 description (Sunfury losing control, mana creatures, chain reaction); quest 10267 description (Duro to the east of Midrealm Post, unpaid surveying equipment, mana creatures); quest 10223 description (crimson armor, ordered to Manaforge Duro, his bow); quest 10209 description (Kanthin holds Glacius as a trophy, stationed at Duro); quest 10256 description (crystal-bearing giant Apex roams the plains west of Manaforge Duro); zone_areas 3734: Daellis 19705, Kanthin 19657, Glacius 19653, Overseer Athanel 20435, Box of Surveying Equipment x26'),
(352314, 1, 3523, 14, 0, 8, 'Cosmowrench', 'Cosmowrench is a small goblin outpost in the Vortex Fields at the far eastern edge of Netherstorm, close beneath Tempest Keep, a miniature Area 52 with its own bruisers, a weapon merchant and a flight master. Its most curious resident is a human named Sab''aoth, who once amused himself by accepting any challenge offered and now runs a reagent and poison business while writing a book about his time with the Twilight''s Hammer. One of his best sellers is the caustic blood of the warp chasers that swarm the Vortex Fields, which only his foul-mouthed imp, Zeppit, can gather safely.', 'warcraft.wiki.gg/wiki/Cosmowrench (Vortex Fields, easternmost edge, near Tempest Keep, miniature Area 52, Harpax, Kerpow, Sab''aoth a human); npc_text 10691 (Sab''aoth: challenges, reagent business, book about his experiences in Twilight''s Hammer); quest 10924 description and reward (warp chaser blood, Zeppit, nasty mouth); zone_areas 3724: Cosmowrench Bruiser, Harpax 20515, Sab''aoth 22479, Kerpow 22491; 3728: Warp Chaser x51, Zeppit 22484; creature_template 22479 subname Reagents & Poison Supplies; creature_template 20515 Harpax flight master, 22491 Kerpow Blastwrench weapon merchant'),
(352315, 1, 3523, 15, 0, 8, 'Tempest Keep', 'Beyond the Tempest Rift at Netherstorm''s eastern edge, the fortress of Tempest Keep hangs apart from the land. Prince Kael''thas Sunstrider made it his seat, and it is the reason the manaforges exist: their energy flows to it, and the Aldor reckon that once the last forge falls, the prince will be left to drain whatever reserves he has stored. Its satellites are the Mechanar, the Botanica, the Arcatraz and the Eye. From Shattrath City, the naaru A''dal sends champions to break into its satellites and to bring the prince to account.', 'warcraft.wiki.gg/wiki/Tempest_Keep (Kael''thas''s stronghold, satellites, Eye raid with Kael''thas); quest 10323 description (one manaforge keeps Tempest Keep functional, Kael will deplete stored energy); npc_text 9926 (energy sent to Tempest Keep); quest 10257 log text (Commander Sarannis in the Botanica); quest 10704 (A''dal: Arcatraz key), Trial of the Naaru chains (A''dal, Shattrath); zone_areas 3842: instance portals and The Arcatraz object'),
(352316, 1, 3523, 16, 0, 8, 'The Stormspire', 'The Stormspire is the seat of the Consortium in Netherstorm, a towering spire reached by an elevator from its base and flanked by the eco-domes Skyperch and Sutheron, where talbuks and lashers thrive under the ethereals'' shields. At its summit, Nexus-Prince Haramad receives visitors as a holographic image, a precaution against his many enemies. Below, dealers sell everything from exotic weapons to rare creatures, Head Engineer Ghabar tends the dome generators, a transmuter whose skill is known in a thousand worlds takes on alchemists, and a Cenarion Expedition envoy bargains for the domes'' secrets. Nexus-guards and alarm bots watch for trouble.', 'quest 10268 description (chamber atop the Stormspire, holographic image); npc_text 9993 (Haramad: many enemies, imaging device a precaution); quest 10423 description (elevator at the base of the spire); warcraft.wiki.gg/wiki/Netherstorm (Sutheron and Skyperch flank the Stormspire); quest 10424 description (main dome generator in Eco-Dome Sutheron); npc_text 10687 (Zarevhi: known in a thousand worlds); quest 10426 description (Aurine negotiating with the ethereals); zone_areas 3738: dealers 19533-19538, 20980, 20981, 20989, Ghabar 20811, Aurine Moonblaze 20871, Nexus-Guard, Alarm Bot; 3875/3876: Talbuk, Farahlon Lasher; creature_template 20811 Ghabar (Head Eco-Dome Engineer), 22427 Zarevhi (quest 10899 Master of Transmutation), 20871 Aurine Moonblaze (Cenarion Expedition)'),
(352317, 1, 3523, 17, 0, 8, 'Manaforge Ara', 'Manaforge Ara, on its own island in the northwest, is the last and best defended of the working forges, and it holds the secret the others only hinted at. Demons labor openly beside the Sunfury here: mo''arg warp-masters and gan''arg tinkers tend the machinery, a doomguard overmaster rules the Trelleum Mine beneath it, and its overseer bears the strangely un-elven name of Azarad. Not every elf is loyal: a Sunfury magister stationed here has offered to defect. Across the bridge at Tuluman''s Landing, a Consortium agent poses as a weapon seller, and the young Aldor Kaylaan waits, sole survivor of the ten who went in.', 'quests 10323, 10365 descriptions (northwest, last manaforge, heavy opposition, Azarad an odd name for a sin''dorei); creature_template 20685 Overseer Azarad (type demon); quest 10432 description (servants of the Legion all over Ara); quest 10317 description (Trelleum Mine underneath Ara); quest 10318 description and reward (Sundown demoted, pilgrimage a lie, doomguard overmaster Grindgarr); quest 10202 description (Sunfury magister wishes to defect, stationed at Ara); quest 10275 description (Tuluman poses as a weapon merchant next to the bridge to Ara); npc_text 10209 (Kaylaan: ten of us went in, all others fell); zone_areas 3722: Mo''arg Warp-Master, Gan''arg Warp-Tinker, Overmaster Grindgarr; 3852: Tuluman, Kaylaan 20780'),
(352318, 1, 3523, 18, 0, 8, 'Forge Base: Oblivion and Gehenna', 'In the north of Netherstorm the Burning Legion has raised two forge bases. At Forge Base: Oblivion, gan''arg mekgineers assemble fel reavers, three of which stand aimed at the Stormspire waiting to be fueled, under Forgemaster Morug. Forge Base: Gehenna is the staging ground for the Legion''s army, where most of its teleporters stand, wrathbringers gather by the regiment, and mo''arg keep the gates in repair under the demon Silroth. Legion fel cannons guard both. Morug and Silroth each carry half of the stone that opens Socrethar''s teleporters, and close by lies Invasion Point: Overlord, the doorway to Socrethar''s own island.', 'quest 10855 description (three fel reavers aimed at the Stormspire, not yet active, gan''arg at Oblivion); quest 10856 description (Oblivion assembles fel reavers, Gehenna staging ground with teleporters, regiment of wrathbringers); quest 10857 description (mo''arg maintain the teleporters); quests 10407, 10508 (Morug and Silroth hold the stone halves); quest 10292 description (Legion cannon at the camps to the north); quests 10409, 10507 log text (Invasion Point: Overlord); zone_areas 3739/3740: Gan''arg Mekgineer, Inactive Fel Reaver, Legion Fel Cannon, Morug 20800, Wrathbringer, Silroth 20801'),
(352319, 1, 3523, 19, 0, 8, 'Socrethar''s Seat', 'Socrethar''s Seat is a craggy island off the northwestern corner of Netherstorm, from which the eredar Socrethar directs the Burning Legion''s campaign. No road reaches it. Only his most trusted lieutenants may pass, by a Legion teleporter that answers only to his stone, and wrath lords and hatecryers keep watch over the crags. It is here that champions of the Aldor and the Scryers come at last to face him, each backed by the power of a leader in Shattrath.', 'quest 10407 description (island in the northwest only his most trusted lieutenants can access, teleportation stone); quests 10409, 10507 log text (Legion teleporter in the northwestern corner, Voren''thal''s Presence); quest 10409 description (Orelis, Karja and Adyen sent); zone_areas 3742: Wrath Lord 20929, Hatecryer 20930, Socrethar 20132'),
(352320, 1, 3523, 20, 0, 8, 'Netherstone', 'The Netherstone is a crystal landmark in the north of Netherstorm that no one saw when this was a lush, green land; its formations were exposed only recently. They yield a mineral the Consortium calls farahlite, after the land''s old name, and the purest grade grows on the backs of the Farahlon giants who roam here under their patriarch, Cragskaar. Beyond it to the northeast lies Eco-Dome Farfield, a remote dome few ethereals visit, where scythetooth raptors nest and an ethereal technician tests repairs to the dome generators.', 'quest 10290 description (landmark not seen when lush, newly exposed formations, farahlite named for the land''s former identity, giants); quest 10293 description (Cragskaar, patriarch of the Farahlon giants); quest 10430 description (Farfield beyond the Netherstone to the northeast, Tashar); quest 10435 description (generator pieces hidden in raptor nests, few ethereals); zone_areas 3850: Farahlon Breaker, Cragskaar 20202; 3874: Scythetooth Raptor, Dome Generator Segment, Tashar 20913'),
(352321, 1, 3523, 21, 0, 8, 'Ruins of Farahlon', 'High in the north of Netherstorm stand the Ruins of Farahlon, where old draenei banners still mark the stones, and which the Consortium''s Zephyrion means to excavate. The Burning Legion moved in first, a few weeks ago. Then one of its dreadlords, Culuthas, killed off all the other demons and summoned hounds and eyes of his own to serve him. He has held the ruins as his own ever since, and an image of Socrethar, the Legion''s master in Netherstorm, hovers close beside him.', 'quest 10335 description (three locations each near a draenei banner); quest 10336 description (Legion moved in weeks ago, Culuthas killed the other demons, summoned his own); creature_text 20138 (ata''mal crystal); quest 10276 description (crystal at the top of the Ruins of Farahlon, held by a demon); warcraft.wiki.gg/wiki/Socrethar (pressured Culuthas to bring the crystal back to the Legion); zone_areas 3741: Hound of Culuthas, Eye of Culuthas, Dead Doomguard, Culuthas 20138, Image of Socrethar 20133'),
(352322, 1, 3523, 22, 0, 8, 'The Protectorate Watch Post', 'On the island east of the Stormspire, the ethereal Protectorate keeps its Watch Post under Commander Ameer. Its soldiers fight on two fronts: against the void lord Dimensius at the ruined Manaforge Ultris, and against the Ethereum, whose Staging Grounds lie directly to the south. There the Ethereum drill behind their perimeter defenses under Captain Zovax, readying for something the commander fears may be a strike on Ultris, and a Protectorate platoon that marched toward them ten days ago has sent no word since. At the post a researcher studies the pollution draining from Ultris, a flesh handler keeps subservient flesh beasts, and a nether drake waits to carry volunteers into battle.', 'quest 10969 description (Watch Post directly east of the Stormspire on the next island); npc_text 10058 (Ameer: void creature and Ethereum); quest 10339 description (Staging Grounds directly south, perimeter defenses, training facility, Captain Zovax); quest 10422 reward (fields of prisons, creatures from across the universe); quest 10385 reward (void energy at this manaforge); quest 10411 (Navuud, run-off of Dimensius); npc_text 10179 (flesh handlers); quest 10438 (Protectorate nether drake); zone_areas 3854/3878; quest 10339 description (preparing for something, perhaps an assault on Ultris); quest 10422 description (platoon gone 10 days)'),
(352323, 1, 3523, 23, 0, 8, 'Manaforge Ultris', 'Manaforge Ultris is the forge that failed. A tear in the nether now gapes atop it, and through it came Dimensius the All-Devouring, a void lord. The blood elves lost both the forge and the mine beneath it. Voidwraiths drift through the ruin, seeping sludge fills the surrounding pools, and in Access Shaft Zeon on its south side lie corpses drained by another void lord, Arconus, which hide flesh beasts waiting to burst out. The Ethereum patrol the Voidwind Plateau around it with nullifiers and jailors, while two Protectorate agents, split up in a firefight, hold out at the mine.', 'creature_text 21504 group 1 (Ultris was a complete disaster); quest 10437 description (tear in the nether atop Ultris that Dimensius came through); quest 10317 description (blood elves lost the mine underneath Ultris); quest 10411 description (seeping sludge in the pools around Ultris); quest 10270 description (Access Shaft Zeon on the south side of Ultris, Protectorate); quests 10345, 10353 and npc_text 10065 (Arconus, withered corpses, flesh beasts, Araxes and Ya-six); zone_areas 3736, 3880, 3735: Unstable Voidwraith, Seeping Sludge, Dimensius 19554, Withered Corpse, Fleshfiend, Ethereum Nullifier, Ethereum Jailor'),
(352324, 1, 3523, 24, 0, 8, 'Celestial Ridge', 'East of Manaforge Ultris, the Celestial Ridge is a forest of arcane crystals where nether dragons nest in every stage of growth, from eggs to full-grown dragons under a leader named Veraku. They hatch and mature quickly, drawing on the strange energies that forged their kind in the destruction of Draenor. Such creatures attract both profiteers and scholars. The ethereal Wind Trader Marid, who keeps a teleport pad on the ridge, wants their essence for a client he would rather not name, while two quiet watchers at the north end of the ridge, Tyri and her companion Jorad Mace, hope to understand them before others rush to exploit them.', 'warcraft.wiki.gg/wiki/Netherstorm (Celestial Ridge, forest of arcane crystals, nether dragon nesting ground); quest 10271 description and reward (nether dragons in various stages of growth, a client K--, sell to the blood elves); quest 10274 description (hatch and mature rapidly, energies that forged their kind in the destruction of Draenor, Veraku); quest 10270 description (teleport pad); quest 10281 reward (Tyri and Jorad Mace); zone_areas 3737: Nether Drake, Nether Dragon, Nether Dragonkin Egg, Ethereal Teleport Pad, Tyri 20110, Jorad Mace 20111'),
(352325, 2, 3523, 1, 0, 8, 'Rocket-Chief Fuselage', 'Rocket-Chief Fuselage commands B.O.O.M. at Area 52 and drives the building of the X-52 Nether-Rocket, the craft in which he means to cruise the Twisting Nether from the comfort of his command chair. He hires newcomers on the spot as Junior Technician 3rd Grade, promises promotion as fast as they bring him parts, and despairs aloud that his crew is at T-minus never. When a netherologist''s report warned that the storm would rip the region apart within months, his only complaint was that the timetable would have to move up.', 'npc_text 9844 (commander of B.O.O.M., T-minus NEVER); quest 10186 description (Junior Technician 3rd Grade); quest 10183 reward (move up the timetable); quest 10237 reward (Legion blaming us, dream of cruising through the Twisted Nether); quest 10249 reward (promotion to first officer); quest 10186 completion text (cruising the Twisting Nether in the comfort of my command chair)'),
(352326, 2, 3523, 2, 0, 8, 'Archmage Vargoth', 'Archmage Vargoth led the Kirin Tor contingent of the Alliance expedition, and when it became clear they were trapped in Outland he took his mages to the Plains of Farahlon and founded Kirin''Var Village. The Kirin Tor had entrusted him with two treasures of Krasus, a powerful sigil and the spellbook holding every spell Krasus mastered, both of them boons in the war against the orcs. When Kael''thas attacked, Vargoth gave his staff to his apprentice Ravandwyr and bade him flee, then was stripped of his possessions and sealed in the Violet Tower. He speaks to outsiders through an image the staff conjures, still wondering how fields that once looked like Westfall were ruined in mere months.', 'quest_template 10179 description (Vargoth''s own account of founding Kirin''Var); quest 10188 description (Sigil of Krasus, boon against the orcs, divested of possessions); quest 10192 description (Krasus''s Compendium, all the spells he mastered, advantage in the war); quest 10174 reward (gave Ravandwyr the staff and told him to flee); npc_text 9901 (image: fields like Westfall mere months ago); warcraft.wiki.gg/wiki/Kirin''Var_Village'),
(352327, 2, 3523, 3, 0, 8, 'Custodian Dieworth', 'Custodian Dieworth administered Kirin''Var Village on Archmage Vargoth''s behalf, and he still does, though he died in the attack with nearly everyone else. Unlike most of the village dead, he kept his memory and identity. He mourns colleagues whose spirits wander in mindless anger, tries to free a few by returning their treasured belongings to their homes, and has never forgotten the crimson-armored archer who led the assault. Bitter toward a prince who once called himself a member of the Kirin Tor, he hungers for vengeance on the Sunfury who toast their victory at Sunfury Hold.', 'quest_template 10179 description (Vargoth left administration of the town to Dieworth); npc_text 9848 (a man who once called himself a member of the Kirin Tor murdered all of us); npc_text 9847 (Morran: only the custodian and I preserved our full identities); quests 10182, 10305, 10306, 10307 (belongings returned); quest 10184 description; quests 10222, 10223 (vengeance; he does not know how to let go)'),
(352328, 2, 3523, 4, 0, 8, 'Nexus-Prince Haramad', 'Nexus-Prince Haramad leads the Consortium, the ethereal trading cartel whose agents work all over Outland. He keeps his chamber atop the Stormspire but greets visitors only as a holographic image, explaining that he has many enemies who would like to see him dead. His people are everywhere, from dealers posing as weapon merchants to nether-stalkers hunting traitors, and those who bring him what he wants are welcome to the hospitality of the Consortium.', 'npc_text 9993 (imaging device, many enemies); quest 10268 description (chamber atop the Stormspire); quest 10265 description (our leader, Nexus-Prince Haramad); quest 10275 description (Tuluman posing as a weapon merchant, another of the nexus-prince''s agents); quest 10269 description (crystal from draenei legend, god-like powers); quest 10276 reward (selflessness, much to think about); nagrand.json 351812 (Consortium at Aeris Landing); quest 10268 reward text (the hospitality of the Consortium)'),
(352329, 2, 3523, 5, 0, 8, 'Commander Ameer', 'Commander Ameer leads the ethereal Protectorate in Netherstorm and addresses everyone else as fleshling. He tells the ethereals'' story plainly. The Ethereum were the ruling class of his homeworld, K''aresh, which his people fled shortly before the void lord Dimensius ravaged it; they vowed vengeance and have hunted him ever since, but vengeance has twisted them, and several nexus-princes broke away to found new factions, the Consortium among them. The Protectorate, he insists, was born as a reaction to the Ethereum, not to Dimensius, and he holds them just as dangerous. He works through transponders and projected images.', 'npc_text 10058, 10059, 10060, 10061 (Ameer''s gossip chain); quests 10339, 10384 (transponder, image); quests 10971, 10972, 10973 (prisoner tags decoded)'),
(352330, 2, 3523, 6, 0, 8, 'Tyri', 'Tyri keeps watch over the nether dragons of the Celestial Ridge from its north end with her companion, Jorad Mace, and the pair take pains not to reveal themselves. She reaches newcomers first through a projection of her current form, urging them to have nothing more to do with Wind Trader Marid, whom she counts a swindler posing as a merchant, and to work with her instead. She has never seen anything like these dragons: they seem to have inherited their sire''s temperament, yet they have become something entirely different.', 'quest 10281 description and reward (projection, Marid a swindler, Tyrygosa of the brood of Malygos, Jorad Mace); quest 10272 description (rumors, descendants of Deathwing); quest 10274 description and reward (powers of use to my flight, displace Veraku, malevolent power); npc_text 9968; quest 10281 description (projection, Marid a swindler); npc_text 9968'),
(352331, 2, 3523, 7, 0, 8, 'Socrethar', 'Socrethar is the eredar who commands the Burning Legion in Netherstorm. His seat is an island of crags off the land''s northwestern corner, cut off from every road: the only way across is a Legion teleporter that answers to his own stone, and his demons guard the heights. Those who come against him face a foe of terrible power, who answers blades with cleaving blows and wards himself against magic while shadow bolts and barrages of fire rain down on his enemies.', 'quest 10407 description (infamous eredar, leads the Legion in Netherstorm, makes draenei shudder, island in the northwest); quest 10410 reward (Ishanah: once a renowned warrior of the Light, pride his only flaw); quest 10380 description (demons the only reason Kael''thas could use Tempest Keep technology); creature_text 20132 (mocks the Aldor army, Kaylaan); smart_scripts 20132 (Cleave, Anti-Magic Shield, Shadow Bolt Volley, Fireball Barrage); quest 10508 description (his teleporters, locked by his stone)'),
(352332, 2, 3523, 8, 0, 8, 'Dimensius the All-Devouring', 'Dimensius the All-Devouring is a void lord who came into Netherstorm through a tear in the nether atop Manaforge Ultris and has made the ruined forge his own. Void creatures go out from him to ravage the island around it, and he proclaims, in a voice that carries far, that time has meaning only to mortals: he is infinite, and in time all will be devoured. The ethereals of the Protectorate are his sworn foes, and their avengers under Captain Saeed stand ready to march on Ultris.', 'quest 10437 description (tear atop Ultris, immune to physical harm, void creatures he sends out); creature_text 19554; npc_text 10059 (Dimensius unleashed his void armies on K''aresh); quests 10438, 10439 description and reward (Captain Saeed and the Avengers, hunted for a thousand years); warcraft.wiki.gg/wiki/Dimensius (Burning Crusade section only)'),
(352333, 3, 3523, 1, 0, 8, 'The X-52 Nether-Rocket', 'On the bridge into Netherstorm, Netherologist Coppernickels studies the ethereal currents and sends newcomers on to Area 52 with his overdue notes, which warn that the nether energies will rip the region apart within months. Rocket-Chief Fuselage simply moves up his timetable. Each new hire becomes a Junior Technician, sent to the Ruins of Enkaat for etherlithium crystals for the engine matrix, while a bot specialist sends a robot to salvage draenei machines. Chief Engineer Trep, who only took the post because the security jobs were gone, still lacks an engine core and hopes mana wraith essence will jump-start the engines. Boots the bartender brews rocket fuel from shale oil and nether ray venom, and the sappers zap their abandoned gear back from the Arklon Ruins.', 'quests 10183, 10260 (Coppernickels on the bridge, report); quests 10186, 10225, 10224, 10226 (crystals, Trep, essence, elemental power); npc_text 9916 (Trep applied for security); quests 10190, 10191 (Alley, Mark V); quests 10342, 10199 (Boots'' fuel); quest 10203 reward (four things sent, three arrived); quest 10221 description (Sparky Uberthruster became Dr. Boom, no helmet)'),
(352334, 3, 3523, 2, 0, 8, 'The Legion Comes for Area 52', 'Papa Wheeler of B.O.O.M. decides that the ethereals scavenging the Heap deserve to be robbed in turn, then sends help against the demons who have seized the Scrap Field. His wife, Mama Wheeler, who works among the ethereals at the Midrealm Post and is not pleased to hear herself called his partner, wants the small fel reaver parts the Legion leaves lying about, and then decides that killing the overseer Doomclaw might scare the demons away. Everyone agrees the Legion is creeping closer, moving in on the goblins'' claims one at a time.', 'quests 10206, 10232, 10333, 10234, 10235, 10237, 10247, 10248, 10249 (descriptions and reward texts); creature_text 19832 (Vomisa: defend us with the Scrap Reaver); quest 10232 reward text and 10234 completion text (the Legion moving in on each claim)'),
(352335, 3, 3523, 3, 0, 8, 'The Curse of the Violet Tower', 'In Area 52 the Kirin Tor apprentice Ravandwyr seeks help for his master, Archmage Vargoth, imprisoned in the cursed Violet Tower where no member of the Kirin Tor may pass. Vargoth gave him his staff and bade him flee the attack, but he sought refuge at the Arklon Ruins, walked straight into a Burning Legion force and lost the staff to the demons; their leader, Ekkorash, holds it now. Ravandwyr is ashamed of his failure, and his master knows nothing of it. He will not rest until the staff is restored to the archmage.', 'quests 10173, 10300, 10174, 10188, 10192, 10301, 10209, 10176, 10256, 10257 (descriptions, log texts and reward texts); creature_text 19938 (Image of Commander Sarannis); npc_text 9828 (Ravandwyr: refuge at Arklon, staff wrested, shame); quest 10173 completion text (I will not rest)'),
(352336, 3, 3523, 4, 0, 8, 'The Ghosts of Kirin''Var', 'Custodian Dieworth and Lieutenant-Sorcerer Morran are the only spirits in Kirin''Var who still know themselves. Dieworth sets out to quiet the angry dead and to lay a few to rest by returning their treasures: a battle-mage''s sword, an heirloom storybook, a high elven cloak and a gnome''s beloved hat. Morran wants to learn what weapon Kael''thas used, for the attack began with a thundering flash and mana creatures have streamed into the village ever since. Dieworth''s thoughts turn to vengeance as well, on the soldiers who toast their victory at Sunfury Hold and on Master Daellis Dawnstrike, who led the attack and now serves at Manaforge Duro.', 'quests 10184, 10185, 10182, 10305, 10306, 10307 (Dieworth); quests 10343, 10239, 10240 (Morran, mana bomb, perimeter); quests 10312, 10316, 10314, 10319, 10320 (annals, focus, Naberius, phylactery, Chapel Yard); quests 10222, 10223 (Sunfury Hold, Daellis); quest 10343 description (thundering noise and flash, mana creatures streaming in)'),
(352337, 3, 3523, 5, 0, 8, 'Shutting Down the Manaforges', 'A''dal sent the Aldor and the Scryers to Netherstorm to learn what Kael''thas is doing with his manaforges, and since they reached the Area 52 inn they have not stopped arguing. Spymaster Thalodien prefers assassinating Kael''s specialists, Exarch Orelis would rather make calculated attacks and gather what can be learned, and the Aldor agree to raid Manaforge B''naar only so that the Scryers will keep gathering information. Each side does its part. The Scryers go after the personnel roster carried by a ballista captain outside B''naar, while the Aldor thin out the magisters and bloodwarders who guard it. What the great purple forges are for, and how far their power reaches, is what both orders mean to find out.', 'creature_text 19467 group 0 (A''dal sent us here to investigate Kael''s activities); npc_text 10022 (arguing since they arrived); quests 10189, 10193, 10204, 10329, 10330, 10338, 10365 (Scryer side); quests 10241, 10243, 10245, 10299, 10313, 10321, 10322, 10323 (Aldor side); quest 10321 reward (cut off from his main source of power); creature_text 19466 group 1 (Orelis: calculated attacks, gather what information we can)'),
(352338, 3, 3523, 6, 0, 8, 'A Pact with the Legion', 'How did Kael''thas master naaru technology so quickly? It should have taken him years even to begin to understand it, and his disciplined army destroys its written orders. The Aldor seize Sunfury briefings from embattled Manaforge Duro that point to outside help in building and running the forges, and follow the trail to Tuluman''s Landing, where the young Kaylaan is the only survivor of ten who went into Manaforge Ara. The Scryers hear from a Sunfury magister stationed at Ara who wishes to defect and swears he has the information they need. Both trails lead into Ara.', 'quests 10328, 10431, 10380, 10381, 10407, 10410, 10409 (Aldor side, descriptions and reward texts); quests 10202, 10432, 10508, 10509, 10507 (Scryer side); npc_text 10209 (Kaylaan); creature_text 20794 (Kaylaan the Lost: brother slain by Voren''thal, sworn enemies allowed into our city), 18537, 18538, 20132; quest 10323 reward (Burning Legion allied with Kael''thas); quest 10328 description (should have taken Kael''thas years; written communication destroyed); quest 10431 description'),
(352339, 3, 3523, 7, 0, 8, 'The Ata''mal Crystal', 'The Aldor and the Scryers both send newcomers to aid the Consortium''s Nether-Stalker Khay''ji, hoping to bring the ethereals around to the naaru''s way of seeing things now that the Consortium''s dealings with the blood elves have soured. Khay''ji has been tasked by Nexus-Prince Haramad with recovering a crystal artifact from the Arklon Ruins, where the Burning Legion has moved in to dig for itself, and the crystal is in the hands of the dreadlord Pentatharon. What the prince truly wants, Khay''ji cannot say for certain.', 'quests 10263, 10264 (Aldor and Scryer breadcrumbs); quests 10265, 10262, 10205, 10266, 10267, 10268, 10269, 10275, 10276 (descriptions and reward texts); creature_text 20138 (Culuthas: ata''mal crystal); quest 10280 description (Haramad gives the ata''mal crystal to be handed to A''dal; Shattrath''s quest, only mentioned)'),
(352340, 3, 3523, 8, 0, 8, 'The Ethereum', 'Commander Ameer suspects that the Ethereum at the Staging Grounds south of his Watch Post are preparing for something, perhaps an assault on Ultris, so volunteers are sent to break through their perimeter, topple Captain Zovax and report through a captured transponder. Other threads lead the same way. Five Consortium dealers have gone missing in two days, and the Consortium suspects the Ethereum. Captain Tyralius took a Protectorate platoon south ten days ago and has not been heard from since, though a faint reading may be a distress signal. And a prison orb salvaged from Ethereum territory seems to hold one of the Protectorate''s own.', 'quests 10339, 10384, 10385, 10405, 10406, 10408 (descriptions and reward texts); creature_text 20454 (Salhadaar); quests 10969, 10970, 10971, 10972, 10973, 10422, 10425; quest 10974 (Bash''ir''s Landing, Blade''s Edge, only mentioned); quest 10970 description (prison orb)'),
(352341, 3, 3523, 9, 0, 8, 'The Eco-Dome Thieves', 'The Consortium brings its eco-domes wherever it goes, but in Netherstorm the generators are failing. At Eco-Dome Midrealm the technician Mehrdad finds generator pieces at the bottom of a lake where crocolisks have taken an interest in them, and sends word to Head Engineer Ghabar at the Stormspire, who orders diagnostics of the main generator in Eco-Dome Sutheron. Others have their own interest in the domes. At the Stormspire, Aurine Moonblaze of the Cenarion Expedition prepares to negotiate with the ethereals for their technology and studies its effects on the life inside, while at the Midrealm Post a goblin who calls himself a simple furrier buys pelts.', 'quests 10417, 10418, 10423, 10424, 10430, 10436, 10440 (descriptions and reward texts); quests 10433, 10434, 10435 (Shauly, Jaxon and Audi); quests 10426, 10427, 10429 (Aurine Moonblaze); quest 10424 description; quest 10426 description (preparing to negotiate)'),
(352342, 2, 3523, 9, 0, 8, 'Kalynna Lathred', 'Kalynna Lathred is a mage who keeps to Area 52 and reads the stars, which she says foretold the arrival of the messenger Archmage Alturus sent her from Karazhan. She left the Kirin Tor in pursuit of knowledge her order forbade, and finds it beyond ironic that she is now asked to help them with that very knowledge. Alturus''s request is no small one: he wants to raise a whole dragon, the dead blue Arcanagos, back from his charred remains. Her help has a price. First she wants two tomes she has long sought: the Tome of Dusk, owned by the orc warlock Nethekurse, and the Book of Forgotten Names, kept by the arakkoa Darkweaver Syth.', 'quest 9631 description (Alturus: devoid of life just like Arcanagos; Kalynna at Area 52), completion text (the stars spoke of your arrival) and reward text (raise a whole dragon); quest 9637 description and log text (left the Kirin Tor for forbidden knowledge; Tome of Dusk, Nethekurse; Book of Forgotten Names, Darkweaver Syth); creature 63367 Kalynna Lathred 17636 (530 3092.56, 3687.07; posarea 3712 Area 52); deadwind_pass.json 4114 part 3 (Alturus sends the bone to her)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(352305, 1, 0, 255, 'The forge''s own console betrays where it came from. B''naar was built on naaru designs, the craft of Tempest Keep bent to the prince''s purposes, and it keeps the failsafe such constructs share: a permanent shutdown that can be set off at the console, given the access crystal carried by Overseer Theredis.', 'quest 10299 description (Aldor: emergency shutdown, a safety mechanism common in naaru constructs, Theredis); quest 10329 description (Scryers: modified naaru technology from Tempest Keep, safeguards, console and access crystal, Theredis)'),
(352305, 2, 0, 255, 'Where B''naar''s four pipelines plunge into the ground, an orb attuned to warp energy took the measure of what they carry, and the Aldor did not like the readings. The energies run dangerously high, far more than this broken land can bear, and unless the forges are stopped, what little is left of Outland may be shattered to pieces.', 'quest 10313 description and reward text'),
(352305, 3, 0, 255, 'Magistrix Larynna of the Scryers studied what the bloodgems do to those who use them. Exposure to so much raw energy greatly magnifies the blood elves'' innate addiction to magic, and she was not surprised that Kael gets away with what he does: his subordinates, she says, are all but drunk on it.', 'quest 10204 reward text (magnified addiction, subordinates drunk on it)'),
(352306, 1, 0, 255, 'Khay''ji''s attack did not finish the job. Word came from another of his agents among the Zaxxis that their leader, Warp-Raider Nesaad, still lives and keeps a small ethereal camp in the southwestern corner of the Heap, and Khay''ji wants him dealt with before his operation goes any further.', 'quest 10262 description (took out their leader) and reward text (Nesaad still lives); quest 10205 description (camp in the southwestern corner)'),
(352309, 1, 0, 255, 'Under an illusion, one of the Scryers'' agents slipped into the forge and overheard Commander Dawnforge order Ardonis to send reinforcements to Manaforge Duro, which mana creatures had thrown into chaos. Ardonis protested that Coruu was badly understaffed, until an image of Pathaleon the Calculator appeared: Duro would be reinforced, for Ultris had been a complete disaster, and Prince Kael''thas would tolerate no further delays.', 'quest 10198 description and reward text; creature_text 19831 groups 0-1, 19830 group 0, 21504 groups 0-3; src/server/scripts/Outland/zone_netherstorm.cpp (Dawnforge, Ardonis and Pathaleon image event)'),
(352310, 1, 0, 255, 'A fragment recovered from the ruins told Lieutenant-Sorcerer Morran what had opened the attack: a mana bomb, a weapon he thought even the best minds of Dalaran could never have conceived. The sheer force of its blast tore a rift in the nether, and through it the mana creatures reach the village.', 'quest 10343 reward text (mana bomb, rift in the nether)'),
(352311, 1, 0, 255, 'The tower''s defenses did not fall to force alone. Naberius, another of Vargoth''s apprentices, was an ardent student drawn to necromancy, and when Kael''thas appeared with his forces he seized the chance to betray his master, handing the blood elves the secrets of the tower''s defenses.', 'quest 10319 description (Naberius handed over the secrets to the tower''s defense)'),
(352311, 2, 0, 255, 'The force behind the ward was found at last, by scrying with one of the giant Apex''s crystals as a focus. It led to Commander Sarannis, an advisor of the prince and no mage at all, whom Vargoth remembers from the day the village fell. She does not sustain the curse; she keeps its key, far off in Tempest Keep, and until it is destroyed the tower stays sealed.', 'quest 10256 reward text (Sarannis holds the key); quest 10257 description (enter Tempest Keep and claim the keystone)'),
(352315, 1, 0, 255, 'Among those who served the prince here was Commander Sarannis, who took part in the attack on Kirin''Var. No mage herself, she held the key to the curse on the Violet Tower, and she kept it in the Botanica, well out of reach of the archmage it imprisoned.', 'quest 10256 reward text; quest 10257 log description (the Botanica; offered on the 10256 turn-in)'),
(352315, 2, 10, 255, 'In time the fortress no longer shielded its master. Champions from Shattrath fought their way into the Eye, the satellite where Kael''thas held court, and struck him down in the heart of his own stronghold. Word spread that Kael''thas Sunstrider was dead.', 'mod-individual-progression src/IndividualProgression.cpp (killing Kael''thas 19622 sets PROGRESSION_TBC_TIER_2, state 10); quest 11007 description (the remains of Kael''thas Sunstrider; The Eye, only as a source); quest 11492 description (Kael''thas has risen from the ashes of defeat; Magisters'' Terrace, only as a source); warcraft.wiki.gg/wiki/Kael''thas_Sunstrider (Burning Crusade: defeated in the Eye)'),
(352317, 1, 0, 255, 'Another doubter works in the mine below. Foreman Sundown, demoted from his post, has come to see the pilgrimage from Quel''Thalas to Outland as a lie Kael''thas told to strengthen his forces in Netherstorm, and he has tried in vain to persuade his brethren to leave, all the more with the Burning Legion here.', 'quest 10318 description (demoted, pilgrimage a lie, tried to convince my brethren)'),
(352320, 1, 0, 255, 'Its remoteness has made it a hiding place. The raptor nests of Farfield hold more than eggs: pieces of the ethereals'' own dome generators, taken by two goblins of Area 52 who pass for hunters at the Stormspire and slip out here to stash them.', 'quest 10435 description (pieces hidden in raptor nests, few ethereals); quest 10433 description (sent from Area 52)'),
(352321, 1, 0, 255, 'The prize at the top of the ruins is the ata''mal crystal, an artifact out of draenei legend whose bearer, it is said, gains the powers of a god. The Consortium tracked it here by triangulation and found it already in the Legion''s grip, for the crystal was moving.', 'quest 10276 description and log text (top of the Ruins of Farahlon, crystal moving, Ata''mal Crystal); quest 10269 description (draenei legend, god-like powers)'),
(352322, 1, 0, 255, 'The silence from the south was broken when the platoon''s captain, Tyralius, was freed from an Ethereum cell, gravely hurt but expected to live. His word turned the post''s attention south again: the Staging Grounds hide whole fields of prisons, holding beings taken from every corner of the universe, and the Consortium means to find a way through their locks.', 'quest 10422 reward text'),
(352322, 2, 0, 255, 'For the Protectorate the discovery made its whole reason for being plain. Behind their defenses the Ethereum draw on the void energies of the ruined forge to remake themselves as nexus-stalkers. They are not hunting the void lord at all; they mean to become void.', 'quest 10385 reward text'),
(352324, 1, 0, 255, 'When the first essence was gathered, a shrouded figure appeared at the pad, the projection of someone keeping watch from hiding. It named Marid''s buyers: the ethereal meant to sell the essence to the blood elves like so much candy. Marid, the figure warned, was a swindler wearing an honest trader''s face.', 'quest 10271 description (a client K--) and reward text (sell to the blood elves); quest 10281 description (projection, swindler); creature_template 20154 Shrouded Figure'),
(352325, 1, 0, 255, 'When word reached him that the Burning Legion blamed Area 52 for its losses and meant to come and destroy the town, he could hardly believe it. Yet he would not let demons ruin his dream of cruising through the Nether, and he knew just the goblin to help.', 'quest 10237 reward text'),
(352325, 2, 0, 255, 'That goblin was Doctor Vomisa, and once the doctor''s Scrap Reaver X6000 had saved Area 52 and the rocket, Fuselage decided that skipping a grade was not reward enough. He made the pilot his first officer on the spot and offered the gratitude of the whole town.', 'quest 10249 reward text; quest 10247 description'),
(352326, 1, 0, 255, 'His freedom came with the keystone, brought out of Tempest Keep to the tower to be destroyed. Vargoth met it with amazement and some unease: from the little he had seen of what Farahlon had become, he doubted he wanted to go outside at all, but anything was better than living out his life a prisoner.', 'quest 10257 description (only once the keystone has been destroyed will I regain my freedom) and reward text'),
(352327, 1, 0, 255, 'When the archer, Master Daellis Dawnstrike, was dead at last, the custodian seemed close to tears. It was through, he said, and if he could will himself out of existence he would, but the truth is that he does not know how to let go; that, he supposes, is the price of keeping such strong ties to this place.', 'quest 10223 reward text'),
(352328, 1, 0, 255, 'The surveying equipment was only a means. What the nexus-prince truly wants is a crystal out of draenei legend, said to make its bearer like a god, and he fears that others, the Burning Legion first among them, will dig it up before he can.', 'quest 10269 description'),
(352328, 2, 0, 255, 'The crystal came back to him, and the one who won it from the Legion simply gave it up. Haramad had never thought to see it recovered, let alone handed over freely. He called the deed an inspiration beyond reproach and admitted it had given him much to think about.', 'quest 10276 reward text'),
(352329, 1, 0, 255, 'Ameer set about cataloguing the prisoner tags found in Ethereum territory and in time cracked their code. The back of each tag records where its prisoner is held and what kind of prisoner it is, and the front always bears the same phrase, A Thousand Worlds. He does not know its meaning, but to him it sounds insidious.', 'quests 10971, 10972 descriptions; quest 10973 description (I have cracked the code)'),
(352330, 1, 0, 255, 'Tyri is properly Tyrygosa, of the brood of Malygos: a blue dragon. Word of the strange dragonkin on the ridge has traveled far, and she fears that many will rush to exploit them for profit without understanding what they are, so she and Jorad mean to gain insight into the creatures before others discover them.', 'quest 10281 reward text'),
(352330, 2, 0, 255, 'She came on rumors of a new breed, perhaps even descendants of Deathwing, and found dragons with all the black flight''s ferocity and its hatred of her own, yet entirely alien. Hoping their powers might serve her flight, she had their leader, Veraku, defeated, and now means to win them over with time and a firm show of authority, keeping them from falling under the sway of a malevolent power.', 'quest 10272 description; quest 10274 description and reward text'),
(352331, 1, 0, 255, 'Among the draenei his name is infamous, enough to make most of them shudder, and from that island he gives his orders where none but his most trusted servants may follow. The Aldor hold that his demons are the only reason Kael''thas could ever make use of the technology of Tempest Keep.', 'quest 10407 description; quest 10380 description (the Aldor chain''s step before 10407)'),
(352331, 2, 0, 255, 'High Priestess Ishanah of the Aldor remembers the name. Socrethar was once a renowned warrior of the Light, she says, and pride was his only flaw. Facing an eredar leader is never taken lightly among the Aldor, for a single mistake is likely to cost lives.', 'quest 10410 description and reward text'),
(352331, 3, 0, 255, 'Socrethar''s power did not save him. He fell at last on his own island seat, struck down by the champions who came through his teleporter to face him, and the Legion in Netherstorm lost its master.', 'smart_scripts 20132 (death at Socrethar''s Seat); creature 71631 (530 4946.94, 3849.21)'),
(352332, 1, 0, 255, 'The tear is the source of his safety. It binds him to the void and keeps him phased out of this world, beyond the reach of physical harm. Professor Dabiri of the Protectorate means to lock onto that conduit and destroy it, then destroy Dimensius, beginning with fragments taken from the void creatures he sends out.', 'quest 10437 description'),
(352332, 2, 0, 255, 'The ethereals have cause to hate him. By Commander Ameer''s account, Dimensius unleashed his void armies on their homeworld of K''aresh shortly after the ethereals fled it and laid waste to all that stood in his way, and the Ethereum have hunted him ever since, sworn to vengeance.', 'npc_text 10059 (Ameer)'),
(352332, 3, 0, 255, 'Dimensius was not infinite after all. He fell atop Ultris before Captain Saeed''s avengers and the champions who fought beside them, cut down for all his boasts of devouring the world.', 'creature_text 19554; quest 10439 description and reward text'),
(352332, 4, 0, 255, 'For the Protectorate it ended a hunt of a thousand years. Professor Dabiri, whose people had known nothing but conflict with void creature and ethereal alike for all that time, rejoiced that one of their most hated enemies lay dead at last, and gave the thanks of a hundred million ethereals.', 'quest 10439 description (hunted Dimensius for a thousand years) and reward text'),
(352333, 1, 0, 255, 'The essence was not enough. Trep''s next idea was an extractor built by Xyrol, which turns the power of the sundered rumblers and warp aberrations on the Crumbling Waste into something solid enough to gather and pour into the engines.', 'quest 10224 description; quest 10226 description'),
(352333, 2, 0, 255, 'Only three of the four pieces of zapped gear ever arrived. The lead sapper has a worse problem, too: an old protege, Sparky Uberthruster, who would not wear his helmet down in the fissure, turned into the infamous Dr. Boom, stole off with most of the sapping equipment to a camp just outside town, and with his Boom Bots has menaced Area 52 ever since.', 'quest 10203 reward text (four sent, three arrived); quest 10221 description'),
(352334, 1, 0, 255, 'It does the opposite. Doomclaw''s death only turns the demons'' attention on the goblins, and what Mama Wheeler hears of his last words sends her into a panic: the Burning Legion is going after Area 52 itself.', 'quest 10235 reward text; quest 10237 description'),
(352334, 2, 0, 255, 'Back in Area 52 the rocket-chief heard that the Legion held the town to blame for its losses and was coming to wipe it out. Fuselage refused to see his dream end that way and sent for Doctor Vomisa, Ph.T., at the Proving Grounds, whose Scrap Reaver X6000 combines fel reaver, ethereal and goblin technology.', 'quest 10237 reward text; quest 10247 description'),
(352334, 3, 0, 255, 'Its test run became a real battle when demons arrived at the Proving Grounds, and the Scrap Reaver held. Area 52 and the X-52 were saved from certain doom, and the grateful rocket-chief promoted the pilot straight to first officer.', 'quest 10248 reward text; creature_text 19832; quest 10249 reward text'),
(352335, 1, 0, 255, 'The staff came back broken, its crystalline headpiece taken, and Ravandwyr reshaped it around a crystal carried by the ghosts of Enkaat. Its magic can pierce the tower''s defenses only in hands outside the Kirin Tor, and through it the archmage''s image appears. The curse can be broken, he says, but not without help, and the first thing he needs is the Sigil of Krasus, which Spellbinder Maryana keeps at Manaforge Coruu.', 'quest 10300 description and reward text; quest 10174 description and reward text; quest 10188 description (offered by the image on the 10174 turn-in)'),
(352335, 2, 0, 255, 'One by one his treasures came back to him: the sigil, Krasus''s Compendium from the houses where a rebellious apprentice and his followers had divided it, the heliotrope oculus that unlocks it from Sunfury Hold, and his familiar Glacius from Summoner Kanthin at Manaforge Duro. Then the golem Ar''kelos fell, and its dampening field with it, yet the curse held. A crystal from the giant Apex served as a scrying focus, and the trail led to Commander Sarannis in Tempest Keep''s Botanica.', 'quests 10188, 10192, 10301, 10209 (descriptions and reward texts); quest 10176 description and reward text; quest 10256 description and reward text; quest 10257 log description (Botanica)'),
(352335, 3, 0, 255, 'The keystone was taken from Commander Sarannis in the Botanica and carried back to the Violet Tower. Once it was destroyed, the curse that had held the archmage since the fall of Kirin''Var would be broken at last.', 'quest 10257 description and reward text'),
(352336, 1, 0, 255, 'A fragment showed it was a mana bomb, whose blast tore open the nether. Seeing the blood elves fight the same mana creatures with defenses fueled by concentrated energy, Morran had their energy sources captured, and with them he set out to ring the village with runes that would hold the creatures back.', 'quest 10343 reward text; quest 10239 description and reward text; quest 10240 description'),
(352336, 2, 0, 255, 'Yet the quieted spirits keep rising. The village annals, recovered from the town hall, show a pattern: the most aggressive ghosts are the most powerful and highest ranking Kirin Tor who lived here, while the townspeople and tradesmen are all but overlooked. Someone, it seems, is choosing them.', 'quest 10312 description and reward text; quest 10316 description (deliberate, targeting the most powerful mages)'),
(352336, 3, 0, 255, 'A necromantic focus, hidden in the houses across the covered bridge, pointed to the culprit: Naberius, the archmage''s other apprentice, drawn to necromancy, who betrayed the tower''s defenses to Kael''thas and has since become a lich. His phylactery was found, and Dieworth means to smash it when the lich is confronted in the Chapel Yard, leaving him open to attack.', 'quests 10316, 10314 descriptions and reward texts; quest 10319 description and reward text'),
(352336, 4, 0, 255, 'Naberius was destroyed, and with him his enslavement of the fallen. Dieworth counted it a great achievement, yet he could not help thinking that the village might have stood a chance against Kael''thas had the apprentice''s loyalties been in the right place that day.', 'quest 10320 description and reward text'),
(352337, 1, 0, 255, 'One of the first things the Scryers learned came from the forge''s own magisters. Magistrix Larynna tried the bloodgem shards they use to siphon energy and found that the rush feeds the blood elves'' hunger for magic far beyond its natural measure, enough to explain, she thought, why Kael''s followers let him get away with so much.', 'quest 10204 description and reward text'),
(352337, 2, 0, 255, 'The roster gave the Scryers their targets among Kael''s specialists, and the forge itself gave up a greater secret. The manaforges are naaru craft, modified from the technology of Tempest Keep, and like most naaru constructs they carry a safeguard: an emergency shutdown, begun at each forge''s console with an access crystal kept by its overseer.', 'quest 10243 description (Aldor: Scryers picking assassination targets from the roster); quest 10299 description; quest 10329 description'),
(352337, 3, 0, 255, 'Aldor readings at B''naar''s pipelines showed what was at stake. The warp energies they carry are dangerously high, since Tempest Keep''s recharging mechanisms were never meant to work so close to the land, and unless the forges are shut down, what remains of Outland could be shattered.', 'quest 10313 description and reward text'),
(352337, 4, 0, 255, 'One by one the forges went dark: B''naar, then Coruu, then Duro, where swarms of mana creatures had thrown the garrison into chaos, and at last Ara, the most heavily defended of all. Kael''thas had lost the last of his working forges. Yet at Ara the shutdown uncovered something worse: the Burning Legion, allied with Kael''thas Sunstrider, and word of it would soon reach Shattrath.', 'quests 10321, 10322, 10330, 10338 (Coruu and Duro); quest 10323 description and reward text; quest 10365 description and reward text'),
(352338, 1, 0, 255, 'The answer was the Burning Legion. At Manaforge Ara its servants labor beside the Sunfury, and the truth can no longer be hidden: Kael''thas Sunstrider has allied himself with the Legion, and his army and the demons now serve under the same banner.', 'quest 10380 description; quest 10432 description; quests 10323, 10365 reward texts'),
(352338, 2, 0, 255, 'For the Aldor the discovery came at a bitter price. Kaylaan, who had never once failed an order, would go no further. The naaru, he said, had given the holiest city to the draenei''s enemies and then asked the Aldor to die fighting their wars; he renounced the order and sent word to Orelis that the naaru could fight their own fights from now on.', 'quest 10380 reward text; quest 10381 description'),
(352338, 3, 0, 255, 'Behind the alliance stands the eredar Socrethar, who leads the Legion in Netherstorm from an island that only his own teleporters reach. Both orders took the halves of his teleportation stone from Forgemaster Morug at Forge Base: Oblivion and from Silroth at Forge Base: Gehenna, and with the stone whole, the way to his seat lay open to whoever had the strength to go.', 'quest 10407 description and reward text; quest 10508 description and reward text'),
(352338, 4, 0, 255, 'The Aldor came to Socrethar''s Seat with Adyen the Lightwarden, who offered the eredar a chance to repent, as the naaru''s law commands. Socrethar scoffed at the mighty Aldor army and brought out Kaylaan, his mind clouded: Voren''thal had slain his brother, he said, and Shattrath and its naaru must fall. He fought the Lightwarden who had trained him until Ishanah came and offered herself in his place. Socrethar struck her down, and Kaylaan broke free, called on the Light and raised her, then fell to Socrethar''s magic before the eredar died. Not even Ishanah''s prayers could bring him back.', 'quest 10409 description and reward text; smart_scripts 23491, 18537, 1853700, 2013200-2013202, 2079400-2079402, 1853800 (the Aldor event, started from Adyen''s gossip 8117, shown only with 10409); creature_text 18537 (Adyen), 20132 (Socrethar groups 0-5), 20794 (Kaylaan the Lost), 18538 (Ishanah)'),
(352338, 5, 0, 255, 'The Scryers went to Socrethar''s Seat carrying an orb from Voren''thal, whose frail health kept him in Shattrath but whose power it projected across the land. Released against Socrethar, the Seer''s power weakened the eredar and laid him open to attack, and he fell. Voren''thal counted it a decisive victory over Kael''thas''s new masters: as word of the prince''s allegiance spread, he expected more people to come around to the Scryers'' way of seeing things.', 'quest 10507 description and reward text; item 30259 Voren''thal''s Presence (description), spell 36314 The Seer''s Presence (use on Socrethar to weaken him; damage taken up, damage done down); conditions 17/36314 (target Socrethar 20132)'),
(352339, 1, 0, 255, 'Pentatharon''s crystal proved to be nothing special, but the Legion was plainly searching for something in particular, and Khay''ji hoped it was not the crystal the nexus-prince wanted so badly. Meanwhile he settled scores with the Zaxxis traitors at the Heap, ethereals who had broken with the Consortium to deal with the Sunfury.', 'quest 10265 completion and reward texts; quest 10262 description'),
(352339, 2, 0, 255, 'The trail ran on to the Midrealm Post, where the blood elves had refused to pay for surveying equipment delivered to Manaforge Duro. Recovered, the equipment went to Haramad at the Stormspire, and he revealed his true aim: a crystal from draenei legend, said to bestow godlike powers on its bearer and in danger of being unearthed by the Legion. The equipment would find it by triangulation.', 'quests 10266, 10267, 10268 descriptions and reward texts; quest 10269 description'),
(352339, 3, 0, 255, 'Triangulation points near Manaforge Ultris and far to the west, reported to his agents Hazzin and Tuluman, placed the crystal atop the Ruins of Farahlon. It was moving, which meant it had already been found, and it proved to be the ata''mal crystal, held by the demon who rules the ruins.', 'quests 10269, 10275 reward texts; quest 10276 description and log text'),
(352339, 4, 0, 255, 'The crystal was taken from the dreadlord Culuthas and brought to the Stormspire, and Haramad, who had thought it beyond anyone''s reach, was moved that it was simply handed over. True to his word, he resolved to send the ata''mal crystal on to the naaru A''dal in Shattrath City, carried by the one who had won it.', 'quest 10276 reward text; creature 20138 Culuthas (carries the crystal; creature_text 20138); quest 10280 description (offered by Haramad on the 10276 turn-in; the quest itself is Shattrath''s)'),
(352340, 1, 0, 255, 'The Ethereum hide their plans well. Their data cells hold nothing, and only someone who drinks an Ethereum essence, at real risk to the mind, can see the relays that carry their secrets. What the relays hold is worse than an assault: the Ethereum are not hunting Dimensius but becoming void, using the ruined manaforge''s void energy to bond themselves into nexus-stalkers.', 'quest 10384 reward text; quest 10385 description and reward text'),
(352340, 2, 0, 255, 'Ameer struck at the transformation through the manaforge energy tube the Ethereum use as a conduit, and a holographic demolitionist overloaded it. Then the force fields around Nexus-King Salhadaar were brought down, and Salhadaar, who had waged his crusade against all who stood in his way for a thousand years or more, was destroyed.', 'quests 10405, 10406, 10408 descriptions and reward texts; creature_text 20454'),
(352340, 3, 0, 255, 'A captured Protectorate soldier was found alive in the Staging Grounds and brought home to the Watch Post. His platoon had been ambushed on the island''s upper ledges by ethereals who looked like Ethereum but wore wrappings of the void, and only Captain Tyralius had been spared, likely for a cell. Ameer judged the soldier might be the key to the whole Ethereum operation.', 'quest 10425 description and reward text (Captured Protectorate Vanguard 20763 in the Staging Grounds, area 3878; turned in to Ameer)'),
(352340, 4, 0, 255, 'Captain Tyralius was found alive in an Ethereum prison, badly wounded. He spoke of fields of prisons like the one that held him, full of creatures from all across the universe, and the Consortium began working on ways to break the Ethereum''s locks.', 'quest 10422 reward text'),
(352340, 5, 0, 255, 'From the prisoners'' tags Ameer broke the Ethereum''s code and combined their prison keys into a tablet that read: a thousand worlds shattered, a thousand more to overcome, by the will of the Nexus-King. On its back was a name, the stasis chambers of Bash''ir, and the trail led on to Bash''ir''s Landing in Blade''s Edge.', 'quests 10971, 10972, 10973 descriptions and reward texts; quest 10974 (Blade''s Edge, only a source)'),
(352341, 1, 0, 255, 'Ghabar''s readings matched Mehrdad''s exactly: equipment had failed or gone missing. A prototype repair kit, tested by Tashar at distant Eco-Dome Farfield, worked, but Tashar saw the pattern in the damage. Key pieces of generator units were missing from a number of sites. This was no accident: the Consortium was being stolen from, and Ghabar began to think of locking down the Stormspire.', 'quests 10424, 10430, 10436 reward texts; quest 10440 description and reward text'),
(352341, 2, 0, 255, 'The furrier is nothing of the kind. Shauly Pore was sent from Area 52 to appraise the technology the ethereals use to generate their domes, and he poses as a simple furrier because the ethereals are clever and observant. His masters prefer agents who are not goblins wherever they can find them.', 'quest 10433 description'),
(352341, 3, 0, 255, 'His associates at the Stormspire, Action Jaxon and Audi the Needle, pose as hunters. Out in the field they have been collecting pieces of the domes'' generators and hiding them in the raptor nests of Eco-Dome Farfield, enough for Area 52''s own needs with spares to sell to the Cenarion Expedition at a profit.', 'quest 10434 description; quest 10435 description and reward text'),
(352341, 4, 0, 255, 'Aurine''s tests showed both promise and danger. Focused on the lashers, the domes'' energies accelerated growth until it bred extreme aggression, and talbuks tagged under the dome are watched to see if they mature as fast. With proper control, she believes, such technology could regrow the ruined lands of Outland and Azeroth.', 'quest 10426 reward text; quest 10427 description and reward text'),
(352342, 1, 0, 255, 'With the tomes delivered, Kalynna kept her end of the bargain and bound her helper''s essence to that of the dead dragon. An urn''s energy, released on the Master''s Terrace in Karazhan, would bring life back to the charred remains of Arcanagos; the creature must then be defeated and its essence carried to Alturus at once. Should that fail, the stars warned, a great terror would be loosed upon the skies, a terror known as Nightbane.', 'quest 9637 reward text; quest 9644 description; mod-individual-progression data/sql/world/base/dungeon_karazhan.sql (9644 provides the Blackened Urn 24140, so the text names the urn''s energy, not how it is used)');
